# Register your models here.from django.contrib import adminfrom .models import PriceImagefrom django.utils.safestring import mark_safe@admin.register(PriceImage)class PriceImageAdmin(admin.ModelAdmin):    list_display = ('preview', 'created_at')    readonly_fields = ('preview',)    def preview(self, obj):        return mark_safe(f'<img src="{obj.image.url}" style="max-height: 100px;">')        preview.short_description = "Превью"